const p=$input.first().json.payload;
if(!p?.report_html)throw Error('Ainda não existe coleta ML. Execute o fluxo de inteligência operacional.');
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const queue=`<section><h2>Fila privada para revisão humana</h2><p>Até 50 unidades dos últimos 7 dias, ordenadas por prioridade de auditoria. Os códigos abaixo são referências internas, não identificadores anônimos. Acesse a conversa original somente no ambiente autorizado. Esta fila não autoriza contato com pacientes.</p><div style="overflow:auto"><table><thead><tr><th>Unidade / dia</th><th>Prioridade</th><th>Sinais</th><th>Próximo passo do auditor</th><th>Revisão</th></tr></thead><tbody>${(p.queue||[]).map(s=>`<tr><td>${esc(s.session_id)}<br>${esc(s.day)}</td><td>${esc(s.priority)}</td><td>${esc((s.tags||[]).join(', '))}</td><td>${esc(s.next_step)}<br><small>${esc(s.followup)}</small></td><td>${esc(s.review||'pendente')}</td></tr>`).join('')}</tbody></table></div><p>Use ana_ml.record_review para registrar falha confirmada, sem falha ou inconclusivo. Não inclua dados clínicos na nota. O rótulo é humano; não altera o prompt nem o atendimento automaticamente.</p></section>`;
const html=p.report_html.replace('</main>',queue+'</main>');
const filename='ana-ml-relatorio-'+String(p.collected_at).slice(0,10)+'.html';
return [{json:{coleta:p.collected_at,arquivo:filename,unidades_na_fila:(p.queue||[]).length},binary:{relatorio:{data:Buffer.from(html,'utf8').toString('base64'),mimeType:'text/html',fileName:filename}}}];
